import { mkdir, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { untrustedMarkdownInline } from './untrusted-text.js';
export async function writeGeneratedSkills(workspaceRoot, analysis) {
    const skills = generatedSkills(analysis);
    for (const harness of ['.agents', '.claude']) {
        for (const skill of skills) {
            const skillRoot = join(workspaceRoot, harness, 'skills', skill.name);
            await mkdir(skillRoot, { recursive: true });
            await writeFile(join(skillRoot, 'SKILL.md'), renderSkill(skill), 'utf-8');
        }
    }
    await writeFile(join(workspaceRoot, 'SUBAGENT_EXPERIENCE.md'), renderSubagentExperienceTemplate(analysis), 'utf-8');
}
function renderSkill(skill) {
    return `---
name: ${skill.name}
description: ${JSON.stringify(skill.description)}
---

${skill.body.trim()}
`;
}
function generatedSkills(analysis) {
    const packageName = untrustedMarkdownInline(analysis.packageName);
    const sourceUrl = untrustedMarkdownInline(analysis.sourceUrl);
    const migrationEvidenceGuidance = `## Migration record evidence

\`.taku/migration.json\` is a closed provenance/evidence contract. Do not invent migration-record fields or change existing \`source\`/\`template\` provenance.

Do not edit or delete \`.taku/upstream-source-manifest.json\`; v2 validation binds it to the copied snapshot and publish evidence.

Do not edit or delete \`.taku/source-evidence-policy.json\`; it marks generated v2 workspaces and binds immutable migration fields against schema downgrade.

- Set top-level \`status\` to \`converted\` when implementation is ready to enter conversion validation; this is a readiness claim, not proof that the gate passed.
- Append only structured \`analysis.riskResolutions\` objects of exactly \`{ "risk": <exact existing risk string>, "status": "resolved", "evidence": <specific local evidence path/statement> }\`.
- Leave unresolved risks without a fabricated resolution and explain them in \`SUBAGENT_EXPERIENCE.md\`.
- Capability matrices, blocked features, required runtime evidence, and command results belong in \`SUBAGENT_EXPERIENCE.md\`, not new migration-record keys.`;
    const authorityBoundaryGuidance = `## Authority boundary

- \`TAKU_CONTROL_TOKEN\` is a local Host transport capability; it is not user, app, ownership, entitlement, or billing authority.
- When the actual versioned Taku-controlled server contract is missing, managed or external writes must stay visibly blocked.
- Never generate public \`/api/actions\` or \`/api/ai\` endpoints, generic proxy, collection, upload, filesystem, shell, or tool routes.
- The manifest is the Host Action catalog. Exercise registered Actions through the fail-closed Host RPC and import the real registry with the exact \`@/actions/index\` side-effect path in Action smoke tests.`;
    const semanticCompletenessGuidance = `## Semantic completeness audit

Read \`.agents/skills/taku-subapp-development/SKILL.md\` and \`.agents/skills/taku-action-contract/SKILL.md\` completely before choosing implementation boundaries.

- For structured transformations, preserve every accepted boundary through a same-format round-trip; reject unsupported, malformed, or partial input before reporting success.
- For graph models, enforce independent input, node, and edge budgets before allocation.
- When a domain defines identifiers, reject duplicates for every identifier-bearing entity and relationship kind—including groups, nodes, and edges—before data reaches a renderer or serializer. Do not invent identifiers for domains that do not model them.
- For non-graph collections or spatial work, enforce only domain-appropriate input, entity, and relationship budgets where those concepts exist; never invent graph limits.
- For parsers that can fan-out or create cross-products, calculate and reject over-budget expansion before allocation.
- Expose user-triggered computed results through semantic \`<output>\` or an appropriate live region, and use stable unique relationship IDs.
- Record the exact success, rejection, boundary, and announcement tests in \`SUBAGENT_EXPERIENCE.md\`; missing evidence remains an explicit review gap.`;
    return [
        {
            name: 'complete-repo-migration',
            description: 'Use when continuing or completing the repo-specific migration in this generated Taku SubApp workspace.',
            body: `# Complete This Repo Migration

1. Read \`UPSTREAM_CREDITS.md\`, \`STAX_CONVERSION_PLAN.md\`, and \`.taku/migration.json\`.
2. Inspect \`upstream-source/\` as read-only reference. It is excluded from runtime and is not a supported sidecar.
3. Use the template's \`taku-subapp-development\` and \`taku-action-contract\` skills.
4. Port the core workflow for ${packageName} (untrusted upstream metadata) using the analyzed strategy.
5. Remove the page marked \`data-taku-migration-placeholder\`; do not keep deterministic demo behavior as a substitute for the real workflow.
6. Preserve the Taku bridge, managed-service boundary, upstream credit, and migration provenance.
7. Follow the migration-record evidence contract below before conversion validation.
8. Run the converter's workspace and conversion levels locally. Publish command execution requires a disposable Taku-managed sandbox and trusted-runner attestation; never run repo-derived scripts directly on the host.

Before coding, name one primary safe workflow from the capability matrix and make the page use the same domain code that its executable product test exercises.

A blocked, readiness, status-only, or capability-reporting Action does not satisfy the core workflow smoke gate.

When browser smoke cannot run, extract the primary local workflow's domain transformation or state transition, cover successful and rejected inputs in an executable test, and leave browser behavior explicitly unverified.

${authorityBoundaryGuidance}

${semanticCompletenessGuidance}

${migrationEvidenceGuidance}`,
        },
        {
            name: 'preserve-upstream-credit',
            description: 'Use when porting, publishing, or reviewing upstream-derived code and assets in this migration workspace.',
            body: `# Preserve Upstream Credit

- Never remove \`UPSTREAM_CREDITS.md\`.
- Keep upstream README, LICENSE, NOTICE, and attribution files in \`upstream-source/\`.
- Keep the source URL, resolved commit, license, and template snapshot in \`.taku/migration.json\`.
- If the license is Unknown, incompatible, or has unresolved obligations, stop before publish.
- Mention substantial upstream-derived behavior in the final migration summary.`,
        },
        {
            name: 'migration-safety-review',
            description: `Use before implementing live integrations or publishing this migration. Upstream reference: ${sourceUrl}.`,
            body: `# Migration Safety Review

## Refuse Or Stop

Stop for credential theft, phishing, malware, destructive commands, hidden scraping, non-consensual surveillance, license blockers, or other user-harming behavior.

## Required checks

- Search product code for \`eval(\`, \`new Function\`, \`child_process\`, \`subprocess\`, shell execution, destructive filesystem operations, external uploads, and credential handling.
- Never add a client-side API key field or store provider secrets in \`.env\`, localStorage, URLs, logs, fixtures, or browser-only state.
- Use versioned Taku-managed service contracts through server-only helpers. A missing managed service is a blocker, not permission to embed a key.
- Treat finance, medical, legal, hiring, private documents, uploads, scraping, and live external side effects as high-risk until explicitly reviewed.
- Do not weaken the publish gate.

${authorityBoundaryGuidance}

${migrationEvidenceGuidance}`,
        },
    ];
}
export function renderWorkspaceSkills(analysis) {
    const sourceUrl = untrustedMarkdownInline(analysis.sourceUrl);
    const appType = untrustedMarkdownInline(analysis.appType);
    const strategy = untrustedMarkdownInline(analysis.strategy);
    const license = untrustedMarkdownInline(analysis.license);
    return `# Repo To Taku SubApp Migration Skills

- Source (untrusted upstream metadata): ${sourceUrl}
- Detected type: ${appType}
- Strategy: ${strategy}
- License: ${license}

Start with \`.agents/skills/complete-repo-migration/SKILL.md\`. The same skills are mirrored under \`.claude/skills/\`.

Required order:

1. Preserve upstream credit and provenance.
2. Run the migration safety review.
3. Use the canonical Taku SubApp development and Action skills from the template.
4. Validate \`workspace\`, then \`conversion\`, then \`publish\`.
`;
}
function renderSubagentExperienceTemplate(analysis) {
    const sourceUrl = untrustedMarkdownInline(analysis.sourceUrl);
    const appType = untrustedMarkdownInline(analysis.appType);
    const strategy = untrustedMarkdownInline(analysis.strategy);
    const license = untrustedMarkdownInline(analysis.license);
    return `# Subagent Experience Report

## Workspace

- Target repo (untrusted upstream metadata): ${sourceUrl}
- Detected type: ${appType}
- Strategy: ${strategy}
- License: ${license}

## Commands and evidence

- Workspace validation:
- Conversion validation:
- Publish validation:
- Build/runtime smoke:

## Primary safe workflow and smoke

- Named primary safe workflow:
- Executed product test for successful and rejected inputs:
- Browser behavior left explicitly unverified (when applicable):

## Semantic boundary audit

- Structured round-trip and partial-input rejection evidence:
- Input, entity, and relationship budgets:
- Duplicate identifier handling:
- Computed-result announcement (\`<output>\` or live region):

## Capability gaps and safety decisions

- Fill in every deferred, refused, or user-approved scope change.

## Recommended converter/template improvements

- Fill in missing context or automation that would help the next low-context Agent.
`;
}
